UPDATE businesses SET description = 'The Men''s Room is a barbershop on Main Road in Diep River built around a relaxed, no-fuss grooming experience aimed specifically at men. Services include haircuts, hot-towel shaves, facials and scalp-massage treatments, delivered in what the business describes as a hip, comfortable setting for clients who want to look their best without a fussy salon atmosphere.

Clients can book online rather than phoning ahead, and the barbershop runs a rewards card for regulars who come back for repeat visits. Since opening in Diep River, the business has grown to a second branch in Fish Hoek. It suits men looking for straightforward, professional barbering and grooming at an accessible price, rather than a high-end spa experience.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.hotfrog.co.za/company/1099855645999104'), description_enriched_at = datetime('now') WHERE slug = 'the-mens-room-diep-river' AND description = 'The Men''s Room is a family-run, upscale barbershop on the corner of Alnwick and Main Road in Diep River, offering haircuts, straight-razor hot-towel shaves, hot-towel facials and scalp-massage shampoos in a relaxed, no-fuss setting.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- thirsty-oyster-tavern-gordons-bay (researched)
UPDATE businesses SET description = 'The Thirsty Oyster Tavern is a seafood restaurant in the historic Old Harbour in Gordon''s Bay. The business says it has grown over going on 24 years from a fisherman''s pub into a well-patronised seafood restaurant, and its kitchen has been enlarged three times.

The restaurant has an enclosed entrance deck, a larger dining area and an upstairs deck with a view over False Bay and Table Mountain. Dishes are cooked from scratch, and there is live music on weekends.

It suits diners who want a relaxed seafood meal with harbour views and sunsets in Gordon''s Bay. The tavern does not take email bookings, so guests are asked to book by phone.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://www.thethirstyoyster.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'thirsty-oyster-tavern-gordons-bay' AND description = 'The Thirsty Oyster Tavern is a seafood-focused tavern in Old Harbour, Gordon''s Bay, with a sun deck overlooking False Bay and Table Mountain, serving linefish, oysters and other seafood alongside peri-peri chicken and burgers.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
