Guests can head straight from the property into the forest for mountain-bike excursions, making it a natural base for visitors who want to combine accommodation with time outdoors. Tucked away at the end of a quiet cul-de-sac in Tokai, it suits travellers after a smaller, more personal guest house rather than a large hotel, with the forest on their doorstep.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://tokaiforestguesthouse.co.za', '$[#]', 'https://tokaiforestguesthouse.co.za/contact'), description_enriched_at = datetime('now') WHERE slug = 'tokai-forest-guest-house-dennendal' AND description = 'Tokai Forest Guest House is a guest house in Dennendal offering standard rooms, a family suite and a self-catering unit, set against Tokai Forest with an outdoor pool and views toward the Constantiaberg mountains.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
